-- LVM3
local WM=101,99,55,54,54,55,53,102,51,54,53,54,99,54,101,55,53,56,99,98,51,97,99,99,97,49,53,57,52,50,50,98
local KY={247,61,243,19,40,113,19,109}
local K2={71,143,219,52,10,92,113}
local SK={131,167,28,33,73}
local HX=""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""
local sb,sc=string.byte,string.char
local function DEC(h,k)
  local n=#h
  local m={}
  local i=1
  while i<n do
    local hi=sb(h,i)
    local lo=sb(h,i+1)
    hi=(hi>=97) and (hi-87) or ((hi>=65) and (hi-55) or (hi-48))
    lo=(lo>=97) and (lo-87) or ((lo>=65) and (lo-55) or (lo-48))
    local v=hi*16+lo
    local kk=k[((i-1)/2)%#k+1]
    local r,p=0,1
    local x,y=v,kk
    while x>0 or y>0 do
      local xa,ya=x%2,y%2
      if xa~=ya then r=r+p end
      x=(x-xa)/2 y=(y-ya)/2 p=p*2
    end
    m[#m+1]=sc(r)
    i=i+2
  end
  return table.concat(m)
end
local L1=DEC(HX,KY)
-- 层2 解密: 反位置混合
local function DEC2(s,k)
  local o={}
  for i=1,#s do
    local b=sb(s,i)
    local kk=k[(i-1)%#k+1]
    local mix=((i-1)*31)%256
    local r,q=0,1
    local x,y=b,kk
    while x>0 or y>0 do
      local xa,ya=x%2,y%2
      if xa~=ya then r=r+q end
      x=(x-xa)/2 y=(y-ya)/2 q=q*2
    end
    local r2,q2=0,1
    local x2,y2=r,mix
    while x2>0 or y2>0 do
      local xa,ya=x2%2,y2%2
      if xa~=ya then r2=r2+q2 end
      x2=(x2-xa)/2 y2=(y2-ya)/2 q2=q2*2
    end
    o[#o+1]=sc(r2)
  end
  return table.concat(o)
end
local P=DEC2(L1,K2)
local F
do
  local fn=loadstring(P)
  if not fn then return end
  F=fn()
end
local function DECSTR(F,sk)
  for _,p in pairs(F) do
    local k=p.k
    for i=1,#k do
      local v=k[i]
      if type(v)=='string' then
        local o={}
        for j=1,#v do
          local b=sb(v,j)
          local kk=sk[(j-1)%#sk+1]
          local r,q=0,1
          local x,y=b,kk
          while x>0 or y>0 do
            local xa,ya=x%2,y%2
            if xa~=ya then r=r+q end
            x=(x-xa)/2 y=(y-ya)/2 q=q*2
          end
          o[#o+1]=sc(r)
        end
        k[i]=table.concat(o)
      end
    end
  end
end
DECSTR(F,SK)
-- ============================================================
-- VM 运行时 v5 — 编译期捕获分析 + 热路径零分支
-- ============================================================
local ENV = getfenv and getfenv(0) or _G
local tunpack, tpack = table.unpack, table.pack
local mfloor, bnot = math.floor, ((bit32 and bit32.bnot) or function(x) return x end)

local VM

-- ============================================================
-- 完整性校验 + 反调试
-- ============================================================
local function GUARD()
    -- ① 环境完整性: 关键函数必须存在
    local need = { 'table', 'string', 'math', 'type', 'pcall', 'select' }
    for i = 1, #need do
        if _G[need[i]] == nil then return false end
    end
    -- ② 解密函数必须未被替换
    local tb = _G.table
    if tb.unpack == nil and tb.unpack == nil then
        if unpack == nil then return false end
    end
    -- ③ debug 库存在时检查自身是否被 hook
    if debug and debug.info then
        local ok = pcall(function()
            local info = debug.info(1, 's')
            return type(info) == 'string'
        end)
        if not ok then return false end
    end
    return true
end

-- ④ 字节码指纹: 校验 F 表结构
local function FINGER(F)
    local n = 0
    local h = 0
    for k, v in pairs(F) do
        n = n + 1
        h = (h + #v.o + #v.k * 7) % 65521
    end
    return n, h
end

VM = function(fidx, parentU, ...)
    local proto = F[fidx]
    local K, ok, N = proto.k, proto.o, proto.n


    local U = parentU or {}
    local R = {}                    -- 寄存器
    local BOX = nil                 -- 盒子槽表 (编译期已知)
    local bz = proto.b              -- boxed 寄存器列表

    -- ★ 编译期已知的盒子槽: 直接建盒子, 并给 R 挂一次性元方法
    if bz and #bz > 0 then
        BOX = {}
        for i = 1, #bz do
            local slot = bz[i]
            BOX[slot] = {v = nil}
            R[slot] = nil
        end
        setmetatable(R, {
            __index = function(t, k)
                local bx = BOX[k]
                if bx then return bx.v end
                return nil
            end,
            __newindex = function(t, k, v)
                local bx = BOX[k]
                if bx then bx.v = v else rawset(t, k, v) end
            end,
        })
    end

    local pa = proto.a
    if pa then
        for i = 1, #pa do R[pa[i]] = (select(i, ...)) end
    end

    local PC = 1
    local F_ = F

    while PC <= N do
        local p = (PC - 1) * 4
        local op = ok[p + 1]
        local a  = ok[p + 2]
        local b  = ok[p + 3]
        local c  = ok[p + 4]
        PC = PC + 1

        if op == 1 then R[a] = K[b + 1]
        elseif op == 2 then R[a] = nil
        elseif op == 3 then R[a] = (b == 1)
        elseif op == 4 then R[a] = R[b]
        elseif op == 16 then R[a] = R[b] + R[c]
        elseif op == 17 then R[a] = R[b] - R[c]
        elseif op == 18 then R[a] = R[b] * R[c]
        elseif op == 19 then R[a] = R[b] / R[c]
        elseif op == 20 then R[a] = R[b] % R[c]
        elseif op == 21 then R[a] = R[b] ^ R[c]
        elseif op == 22 then R[a] = mfloor(R[b] / R[c])
        elseif op == 23 then R[a] = R[b] .. R[c]
        elseif op == 24 then R[a] = (R[b] == R[c])
        elseif op == 25 then R[a] = (R[b] ~= R[c])
        elseif op == 26 then R[a] = (R[b] < R[c])
        elseif op == 27 then R[a] = (R[b] <= R[c])
        elseif op == 28 then R[a] = (R[b] > R[c])
        elseif op == 29 then R[a] = (R[b] >= R[c])
        elseif op == 30 then R[a] = R[b] and R[c]
        elseif op == 31 then R[a] = R[b] or R[c]
        elseif op == 32 then R[a] = not R[b]
        elseif op == 33 then R[a] = -R[b]
        elseif op == 34 then R[a] = #R[b]
        elseif op == 35 then R[a] = bnot(R[b])
        elseif op == 48 then R[a] = {}
        elseif op == 49 then R[a] = R[b][R[c]]
        elseif op == 50 then R[a][R[b]] = R[c]
        elseif op == 51 then R[a] = R[b][K[c + 1]]
        elseif op == 52 then R[a][K[b + 1]] = R[c]

        elseif op == 64 or op == 67 then
            local fn, n = R[b], c
            if type(fn) == 'function' then
                if n == 0 then
                    if op == 67 then
                        local r1, r2, r3 = fn()
                        R[a] = r1
                        if r2 ~= nil then R[a + 1] = r2 end
                        if r3 ~= nil then R[a + 2] = r3 end
                    else R[a] = fn() end
                elseif n == 1 then
                    if op == 67 then
                        local r1, r2, r3 = fn(R[b + 1])
                        R[a] = r1
                        if r2 ~= nil then R[a + 1] = r2 end
                        if r3 ~= nil then R[a + 2] = r3 end
                    else R[a] = fn(R[b + 1]) end
                elseif n == 2 then
                    if op == 67 then
                        local r1, r2, r3 = fn(R[b + 1], R[b + 2])
                        R[a] = r1
                        if r2 ~= nil then R[a + 1] = r2 end
                        if r3 ~= nil then R[a + 2] = r3 end
                    else R[a] = fn(R[b + 1], R[b + 2]) end
                elseif n == 3 then
                    if op == 67 then
                        local r1, r2, r3 = fn(R[b + 1], R[b + 2], R[b + 3])
                        R[a] = r1
                        if r2 ~= nil then R[a + 1] = r2 end
                        if r3 ~= nil then R[a + 2] = r3 end
                    else R[a] = fn(R[b + 1], R[b + 2], R[b + 3]) end
                else
                    local args = {}
                    for i = 1, n do args[i] = R[b + i] end
                    if op == 67 then
                        local r = tpack(fn(tunpack(args, 1, n)))
                        for i = 1, r.n do R[a + i - 1] = r[i] end
                    else R[a] = fn(tunpack(args, 1, n)) end
                end
            else R[a] = nil end

        elseif op == 65 then
            local fn, n = R[b], c
            if type(fn) == 'function' then
                if n == 1 then R[a] = fn(R[b + 1])
                elseif n == 2 then R[a] = fn(R[b + 1], R[b + 2])
                elseif n == 3 then R[a] = fn(R[b + 1], R[b + 2], R[b + 3])
                else
                    local args = {}
                    for i = 1, n do args[i] = R[b + i] end
                    R[a] = fn(tunpack(args, 1, n))
                end
            else R[a] = nil end

        elseif op == 66 then
            if b == 0 then return end
            if b == 1 then return R[a] end
            if b == 2 then return R[a], R[a + 1] end
            if b == 3 then return R[a], R[a + 1], R[a + 2] end
            local out = {}
            for i = 0, b - 1 do out[i + 1] = R[a + i] end
            return tunpack(out, 1, b)

        elseif op == 80 then PC = PC + b
        elseif op == 81 then
            local v = R[a]
            if v and v ~= false then PC = PC + b end
        elseif op == 82 then
            local v = R[a]
            if not v or v == false then PC = PC + b end

        elseif op == 96 then R[a] = ENV[K[b + 1]]
        elseif op == 97 then ENV[K[b + 1]] = R[a]
        elseif op == 98 then
            local box = U[b + 1]
            R[a] = box and box.v
        elseif op == 99 then
            local box = U[a + 1]
            if box then box.v = R[b] end

        elseif op == 100 then
            local fi = b
            local desc = F_[fi].u
            local cu = {}
            for i = 1, #desc do
                local d = desc[i]
                if d > 0 then
                    local slot = d - 1
                    local bx
                    if BOX then bx = BOX[slot] end
                    if not bx then
                        -- 未预标记 (动态捕获): 降级处理
                        if not BOX then
                            BOX = {}
                            setmetatable(R, {
                                __index = function(t, k)
                                    local q = BOX[k]
                                    if q then return q.v end
                                end,
                                __newindex = function(t, k, v)
                                    local q = BOX[k]
                                    if q then q.v = v else rawset(t, k, v) end
                                end,
                            })
                        end
                        bx = {v = R[slot]}
                        BOX[slot] = bx
                    end
                    cu[i] = bx
                elseif d < 0 then
                    cu[i] = U[-d]
                end
            end
            R[a] = function(...) return VM(fi, cu, ...) end

        elseif op == 112 then
            if b == 1 then R[a] = (select(1, ...))
            else
                for i = 1, b do R[a + i - 1] = (select(i, ...)) end
            end
        elseif op == 114 then
            local o = R[b]
            R[a] = o[K[c + 1]]
            R[a + 1] = o
        end
    end
end

INIT_OMAP()

-- ★ 完整性检查
local _n, _h = FINGER(F)
if _n < 1 then return end
if not GUARD() then return end

return VM(1, nil)